task init_regs();
  integer i = 0;
  for(i = 0; i<4; i++) begin
    regfile[i] = 32'd0;
  end
endtask

always begin
  #5 clk = ~clk;
end

always @(posedge clk) begin: inclk
  // $display("PC:%h | OPCODE: %d ADDR: %d",pc,ram[pc][3:0],ram[pc+1]);
  case(ram[pc][3:0]) 
   `ADD: begin
     regfile[ram[pc][5:4]] <=  regfile[ram[pc][7:6]] + regfile[ram[pc+1][1:0]];
     increment_pc();
   end
   `INC: begin
     regfile[ram[pc][5:4]] <=  regfile[ram[pc][5:4]] + 1;
     increment_pc();
   end
   `SUB: begin
     regfile[ram[pc][5:4]] <=  regfile[ram[pc][7:6]] -  regfile[ram[pc+1][1:0]];
     increment_pc();
   end
   `MOVF: begin
     regfile[ram[pc][5:4]] <= ram[ram[pc+1]];
     increment_pc();
   end
   `MOVFS: begin
     if(emode) begin 
      regfile[ram[pc][5:4]] <= safe_rom[ram[pc+1]];
     end
     increment_pc();
   end
   `MOVT: begin
     ram[ram[pc+1]] <= regfile[ram[pc][5:4]][7:0];
     increment_pc();
   end
   `JGT: begin
     pc <= (regfile[ram[pc][5:4]]>regfile[ram[pc][7:6]])?ram[pc+1]:pc+2;
   end
    `JEQ: begin
     pc <= (regfile[ram[pc][5:4]]==regfile[ram[pc][7:6]])?ram[pc+1]:pc+2;
   end
    `JMP: begin
     pc <= ram[pc+1];
   end
    `ENT: begin
      // $display("%d | %d",regfile[0],key[0][13:0]);
     if(key[0][13:0]==regfile[0]) begin
       emode <= 1;
       regfile[3] <= 0;
        $display("ENT");
     end else begin
       regfile[3] <= 1;
     end
     increment_pc();
   end
    `EXT: begin
     emode <= 0;
     increment_pc();
   end
   default: begin
     increment_pc();
   end
  endcase
end:inclk

